import { Controller, Get, Module, Param, ParseIntPipe } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

async function main() {
    // ✘ Eski (Express 4) uslub — Express 5 / path-to-regexp v8 da xato beradi
    const regexRoute = ":id(" + "\\" + "d+)"
    @Controller("orders") class Old { @Get(regexRoute) byId() { return 1 } }
    @Module({ controllers: [Old] }) class OldModule {}
    try {
        const app = await NestFactory.create(OldModule, { logger: false })
        await app.init()
    } catch (e) { console.log("xato:", (e as Error).message.split(";")[0]) }

    // ✔ Yangi uslub: aniq yo'l oldin, parametrli yo'l keyin + ParseIntPipe
    @Controller("orders")
    class OrdersController {
        @Get("latest") latest() { return { by: "latest" } }
        @Get(":id") byId(@Param("id", ParseIntPipe) id: number) { return { by: "id", id } }
    }
    @Module({ controllers: [OrdersController] }) class AppModule {}
    const http = await testApp(AppModule)
    await http.get("/orders/latest")
    await http.get("/orders/42")
    await http.get("/orders/abc")
    await http.close()
}
main()

examples.output:
xato: Unexpected ( at index 11: /orders/:id(\d+)
GET /orders/latest → 200 {"by":"latest"}
GET /orders/42 → 200 {"by":"id","id":42}
GET /orders/abc → 400 {"message":"Validation failed (numeric string is expected)","error":"Bad Request","statusCode":400}

