import { Body, Controller, Get, Module, Param, Post } from "@nestjs/common"

@Controller("books")
class BooksController {
    private books = [{ id: 1, title: "O'tkan kunlar" }]
    @Get() list() { return this.books }
    @Get(":id") one(@Param("id") id: string) { return this.books.find(b => b.id === Number(id)) ?? { error: "topilmadi" } }
    @Post() create(@Body() b: { title: string }) { const book = { id: this.books.length + 1, ...b }; this.books.push(book); return book }
}

@Module({ controllers: [BooksController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/books")
    await http.post("/books", { title: "Mehrobdan chayon" })
    await http.get("/books/2")
    await http.get("/books/9")
    await http.close()
}
main()

