import { BadRequestException, Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"

@Injectable()
class ParseDatePipe implements PipeTransform<string, Date> {
    transform(v: string) {
        const d = new Date(v)
        if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || Number.isNaN(d.getTime())) throw new BadRequestException(`"${v}" sana emas (YYYY-MM-DD)`)
        return d
    }
}

