import { Controller, Get, Module } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

@Controller("slow")
class SlowController { @Get() get() { return "tayyor" } }

@Module({ controllers: [SlowController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.use((req: Request, res: Response, next: NextFunction) => {
        const t = Date.now()
        const orig = res.writeHead.bind(res)
        res.writeHead = ((...a: Parameters<typeof orig>) => { res.setHeader("X-Response-Time", `${Date.now() - t}ms`); return orig(...a) }) as typeof res.writeHead
        next()
    }))
    const r = await http.get("/slow")
    console.log("sarlavha bor:", /^\d+ms$/.test(r.headers.get("x-response-time") ?? ""))
    await http.close()
}
main()

